import {
  cleanText, normalisePhone, validateDateOfBirth, validateName, validatePhone,
} from './validation.js';
import {
  GENDERS, IDENTIFICATION_TYPES, QUALIFICATIONS, RELATIONSHIPS,
} from './application-schema.js';
import { MAX_AMOUNT_MINOR } from './payment-schema.js';

/** Every editable field, in the order the editor shows them. The login email is deliberately not here. */
export const STUDENT_RECORD_FIELDS = Object.freeze([
  'firstName', 'middleName', 'surname', 'dateOfBirth', 'gender', 'nationality',
  'phoneNumber', 'residentialAddress', 'countryOfResidence',
  'contactName', 'contactRelationship', 'contactPhone',
  'highestQualification', 'institutionAttended', 'completionYear',
  'identificationType', 'identificationNumber',
  'studentNumber', 'feeDueMinor',
]);

export const STUDENT_NUMBER_RE = /^[A-Z0-9][A-Z0-9./-]{2,31}$/;

const ID_NUMBER_RE = /^[\p{L}\p{N}][\p{L}\p{N} ./-]*[\p{L}\p{N}]$/u;

/** Fields the student can see about themselves (all of them: it is their own record). */
export const STUDENT_RECORD_LABELS = Object.freeze({
  firstName: 'First name', middleName: 'Middle name', surname: 'Surname', dateOfBirth: 'Date of birth', gender: 'Gender',
  nationality: 'Nationality', phoneNumber: 'Phone number', residentialAddress: 'Residential address',
  countryOfResidence: 'Country of residence', contactName: 'Emergency contact name', contactRelationship: 'Relationship',
  contactPhone: 'Emergency contact phone', highestQualification: 'Highest qualification', institutionAttended: 'Institution attended',
  completionYear: 'Completion year', identificationType: 'Identification type', identificationNumber: 'Identification number',
  studentNumber: 'Student number', feeDueMinor: 'Fees agreed',
});

/**
 * Validates an edited student record. Only the names are required: older records may lack details that
 * were never collected, and an administrator must still be able to fix what is there. Blank optional
 * fields are saved as empty so an administrator can clear a wrong value.
 * @returns {{ ok: boolean, value: object, errors: Record<string, string> }}
 */
export function validateStudentRecord(input, { now = new Date() } = {}) {
  const src = input && typeof input === 'object' ? input : {};
  const str = (key) => (typeof src[key] === 'string' ? cleanText(src[key]) : '');
  const errors = {};
  const value = {};
  const set = (key, error, normalised) => {
    if (error) errors[key] = error;
    else value[key] = normalised;
  };
  const oneOf = (key, allowed, message) => {
    const text = str(key);
    set(key, text && !allowed.includes(text) ? message : null, text);
  };

  set('firstName', validateName(str('firstName'), { label: 'First name' }), str('firstName'));
  set('middleName', validateName(str('middleName'), { label: 'Middle name', required: false }), str('middleName'));
  set('surname', validateName(str('surname'), { label: 'Surname' }), str('surname'));

  const dob = str('dateOfBirth');
  set('dateOfBirth', dob ? validateDateOfBirth(dob, { now }) : null, dob);
  oneOf('gender', GENDERS, 'Choose a gender from the list.');
  set('nationality', str('nationality') ? validateName(str('nationality'), { label: 'Nationality' }) : null, str('nationality'));

  const phone = str('phoneNumber');
  set('phoneNumber', phone ? validatePhone(phone) : null, phone ? normalisePhone(phone) : '');
  const address = str('residentialAddress');
  set('residentialAddress', address && (address.length < 5 || address.length > 200) ? 'Use between 5 and 200 characters for the address.' : null, address);
  set('countryOfResidence', str('countryOfResidence') ? validateName(str('countryOfResidence'), { label: 'Country of residence' }) : null, str('countryOfResidence'));

  set('contactName', str('contactName') ? validateName(str('contactName'), { label: 'Contact person name' }) : null, str('contactName'));
  oneOf('contactRelationship', RELATIONSHIPS, 'Choose a relationship from the list.');
  const contactPhone = str('contactPhone');
  set('contactPhone', contactPhone ? validatePhone(contactPhone, { label: "Contact person's phone number" }) : null, contactPhone ? normalisePhone(contactPhone) : '');

  oneOf('highestQualification', QUALIFICATIONS, 'Choose a qualification from the list.');
  const institution = str('institutionAttended');
  set('institutionAttended', institution ? validateName(institution, { label: 'Institution attended' }) : null, institution);
  const rawYear = typeof src.completionYear === 'number' ? String(src.completionYear) : str('completionYear');
  const yearOk = /^\d{4}$/.test(rawYear) && Number(rawYear) >= 1900 && Number(rawYear) <= now.getUTCFullYear();
  set('completionYear', rawYear && !yearOk ? `Enter a year from 1900 to ${now.getUTCFullYear()}.` : null, rawYear ? Number(rawYear) : null);

  const idType = str('identificationType');
  const idNumber = str('identificationNumber');
  set('identificationType', idType && !IDENTIFICATION_TYPES.includes(idType) ? 'Choose an identification type from the list.' : null, idType);
  if (idNumber && (idNumber.length < 3 || idNumber.length > 64 || !ID_NUMBER_RE.test(idNumber))) errors.identificationNumber = 'Enter a valid identification number.';
  else value.identificationNumber = idNumber;
  if (idNumber && !idType && !errors.identificationType) errors.identificationType = 'Choose the type of identification.';
  if (idType && !idNumber && !errors.identificationNumber) errors.identificationNumber = 'Enter the identification number.';

  const number = str('studentNumber').toUpperCase();
  set('studentNumber', number && !STUDENT_NUMBER_RE.test(number) ? 'Use 3 to 32 letters, numbers, dots, slashes or hyphens, like CFL-2026-00042.' : null, number);

  const fee = src.feeDueMinor;
  if (fee === null || fee === undefined || fee === '') value.feeDueMinor = null;
  else if (!Number.isInteger(fee) || fee < 0 || fee > MAX_AMOUNT_MINOR) errors.feeDueMinor = 'Enter the agreed fees as an amount, like 45,000.';
  else value.feeDueMinor = fee;

  return { ok: Object.keys(errors).length === 0, value, errors };
}

/** The display name used across the portals. */
export const displayNameOf = ({ firstName = '', surname = '' }) => cleanText(`${firstName} ${surname}`);
